<template>
  <main class="md-page">
    <header class="md-head">
      <div><div class="md-eyebrow">TECH DEVELOPMENT · SOURCING LOOP</div><h1>面辅料新品开发</h1><p>从订单需求、市场寻样、业务确认到可用归档，全程留痕。</p></div>
      <button v-action="['material-development','create']" v-if="canRequest" class="md-primary" @click="openCreate">＋ 新建寻样申请</button>
    </header>

    <section class="md-stats">
      <div class="md-stat"><span>全部申请</span><strong>{{ list.length }}</strong></div>
      <div class="md-stat"><span>待采购寻样</span><strong>{{ count('search_required') + count('searching') }}</strong></div>
      <div class="md-stat"><span>待业务确认</span><strong>{{ count('awaiting_business') }}</strong></div>
      <div class="md-stat"><span>已完成</span><strong>{{ count('completed') }}</strong></div>
    </section>

    <section class="md-toolbar">
      <input v-model="q" placeholder="搜索申请单、订单、面辅料或客户" />
      <select v-model="status"><option value="">全部状态</option><option value="search_required">待重新寻样</option><option value="searching">采购寻样中</option><option value="awaiting_business">待业务确认</option><option value="completed">已完成</option></select>
      <span class="md-muted">{{ filtered.length }} 条记录</span>
    </section>

    <section v-if="loading" class="md-empty">正在加载寻样记录…</section>
    <section v-else-if="!filtered.length" class="md-empty"><div class="md-empty-icon">⌕</div><strong>暂无寻样申请</strong><span>客户订单中遇到未确认的面辅料时，从这里发起市场寻样。</span></section>
    <section v-else class="md-list">
      <article v-for="r in filtered" :key="r.id" class="md-card">
        <div class="md-card-top">
          <div><div class="md-number">{{ r.request_no }} <span class="md-tag" :class="'is-'+r.status">{{ statusLabel(r.status) }}</span></div><h2>{{ r.material_name }} <small>{{ r.material_type === 'fabric' ? '面料' : '辅料' }}</small></h2><div class="md-meta">预下单 {{ r.order_no }} <i>·</i> {{ r.customer_name || '未关联客户' }} <i>·</i> {{ r.style_name || '未填写款名' }}</div></div>
          <button class="md-expand" @click="toggle(r.id)">{{ expanded.has(r.id) ? '收起记录 −' : `寻样记录 ${r.rounds.length} 轮 ＋` }}</button>
        </div>
        <div class="md-requirement"><span>客户要求</span><p>{{ r.customer_requirements }}</p><div v-if="r.requested_spec || r.requested_color" class="md-spec">{{ r.requested_spec || '规格未指定' }}<template v-if="r.requested_color"> · {{ r.requested_color }}</template></div><img v-if="r.reference_image_url" class="md-reference-image" :src="r.reference_image_url" alt="客户参考图片" title="客户参考图片 · 点击放大" @click="openImage(r.reference_image_url, '客户参考图片')"/></div>

        <div v-if="r.status === 'completed'" class="md-pattern-gate">
          <div><b>{{ patternReviewLabel(r.pattern_review_status) }}</b><span>{{ r.pattern_review_status === 'approved' ? '技术已审核，流程已进入打版看板。' : r.pattern_review_status === 'rejected' ? '请查看审核意见后重新提交技术审核。' : '技术审核通过后，自动进入打版看板。' }}</span></div>
          <button v-if="canPatternReview && r.pattern_review_status === 'pending'" class="md-primary md-small" :disabled="busy" @click="reviewForPattern(r,true)">审核通过 · 进入打版</button>
          <button v-if="canPatternReview && r.pattern_review_status === 'pending'" class="md-reject" :disabled="busy" @click="reviewForPattern(r,false)">退回补充</button>
          <button v-if="canRequest && r.pattern_review_status === 'rejected'" class="md-primary md-small" @click="openResubmit(r)">补充资料并重新提交</button>
          <RouterLink v-if="r.pattern_review_status === 'approved'" class="md-board-link" to="/pattern-board">查看打版进度 →</RouterLink>
        </div>

        <div v-if="r.status === 'search_required' && canSource" class="md-inline-form"><div class="md-action-title">{{ r.rounds.length ? '上一轮未通过 · 开始重新寻样' : '采购市场寻样' }} <span>点击后自动记录开始时间</span></div><input v-model="searchNotes[r.id]" placeholder="寻样计划 / 市场范围（选填）"/><button class="md-primary md-small" :disabled="busy" @click="start(r)">开始寻样</button></div>

        <div v-if="r.status === 'awaiting_business' && canReview" class="md-review-note">采购已回传候选，请业务按客户要求确认是否可用。</div>
        <div v-if="expanded.has(r.id)" class="md-history">
          <div class="md-history-title">寻样过程 <span>{{ r.rounds.length }} 轮</span></div>
          <div v-if="!r.rounds.length" class="md-no-round">采购尚未开始市场寻样。</div>
          <div v-for="round in r.rounds" :key="round.id" class="md-round">
            <div class="md-round-line"><b>第 {{ round.round_no }} 轮</b><span>{{ round.decision === 'searching' ? '寻样中' : round.decision === 'awaiting_business' ? '待确认' : round.decision === 'rejected' ? '未通过' : '已确认可用' }}</span></div>
            <div class="md-timegrid"><div><small>采购开始</small><b>{{ fmt(round.started_at) }}</b><em>{{ round.started_by_name || '采购' }}</em></div><div><small>采购回传</small><b>{{ fmt(round.returned_at) }}</b><em>{{ round.returned_by_name || (round.returned_at ? '采购' : '等待回传') }}</em></div><div v-if="round.decided_at"><small>业务确认</small><b>{{ fmt(round.decided_at) }}</b><em>{{ round.decided_by_name || '业务' }}</em></div></div>
            <div v-if="round.decision === 'searching' && canSource" class="md-candidate-form">
              <strong>记录市场找到的候选</strong><div class="md-return-grid"><div class="md-image-column"><ImageUpload v-model="candidate(round.id).candidate_image_url" size="lg" title="候选面辅料实物照片"/><span>上传候选实物照片，供业务判断</span></div><div class="md-fields"><input v-model="candidate(round.id).candidate_name" placeholder="候选面辅料名称 *"/><input v-model="candidate(round.id).candidate_spec" placeholder="规格 / 成分"/><input v-model="candidate(round.id).candidate_color" placeholder="颜色 / 色号"/><input v-model="candidate(round.id).candidate_supplier" placeholder="市场 / 供应商"/><input v-model="candidate(round.id).candidate_price" type="number" min="0" step="0.01" placeholder="参考单价"/><input v-model="candidate(round.id).candidate_note" placeholder="备注"/></div></div><button class="md-primary md-small" :disabled="busy" @click="returnCandidate(r,round)">回传业务确认 · 记录回传时间</button>
            </div>
            <div v-else-if="round.returned_at" class="md-candidate"><img v-if="round.candidate_image_url" class="md-candidate-image" :src="round.candidate_image_url" alt="候选面辅料照片" @click="openImage(round.candidate_image_url, round.candidate_name || '候选面辅料')"/><div><b>{{ round.candidate_name }}</b><div class="md-candidate-meta">{{ [round.candidate_spec, round.candidate_color, round.candidate_supplier].filter(Boolean).join(' · ') }}</div><span v-if="round.candidate_price">参考价 {{ round.candidate_price }}</span><p v-if="round.candidate_note">{{ round.candidate_note }}</p></div></div>
            <div v-if="round.decision === 'awaiting_business' && canReview" class="md-decision"><button class="md-reject" :disabled="busy" @click="reject(r,round)">不符合要求 · 重新寻找</button><button class="md-primary md-small" :disabled="busy" @click="approve(r,round,false)">确认可用并完成</button><button class="md-quiet md-small" :disabled="busy" @click="approve(r,round,true)">确认并加入面辅料档案</button></div>
            <div v-if="round.rejection_reason" class="md-reject-reason"><b>重新寻找原因</b>{{ round.rejection_reason }}</div>
          </div>
          <div v-if="r.status === 'completed'" class="md-complete">✓ 已于 {{ fmt(r.completed_at) }} 确认为可用，流程已闭环<span v-if="r.accepted_material_id"> · 已加入面辅料档案 #{{ r.accepted_material_id }}</span></div>
          <div class="md-events"><span v-for="e in r.events" :key="e.id">{{ fmt(e.created_at) }} · {{ e.actor_name }} · {{ eventLabel(e.action) }}<template v-if="e.details">：{{ e.details }}</template></span></div>
          <div v-for="review in r.pattern_reviews || []" :key="'pr-'+review.id" class="md-review-history">打版准入{{ ({ approved: '通过', rejected: '退回', resubmitted: '补充后重提' })[review.decision] || review.decision }} · {{ review.reviewer_name }} · {{ fmt(review.created_at) }}<template v-if="review.note"> · {{ review.note }}</template></div>
        </div>
      </article>
    </section>

    <div v-if="showCreate" class="md-overlay"><form class="md-modal" @submit.prevent="create">
      <div class="md-modal-head"><div><small>{{ editingId ? 'PATTERN REVIEW RESUBMISSION' : 'NEW MATERIAL REQUEST' }}</small><h2>{{ editingId ? '补充资料并重新提交审核' : '新建面辅料寻样' }}</h2></div><button type="button" class="md-close" @click="showCreate=false">×</button></div>
      <label>关联预下单 <select v-model="form.pre_order_id" required :disabled="!!editingId"><option value="">请选择销售预下单</option><option v-for="o in preOrders" :key="o.id" :value="o.id">{{ o.pre_order_no }} · {{ o.customer_name }} · {{ o.style_name || '未填写款名' }}</option></select><small v-if="!preOrders.length" class="md-no-preorder">当前没有可用预下单，请先到 <RouterLink to="/pre-orders" target="_blank">销售 → 预下单</RouterLink> 新增。</small><small v-else class="md-no-preorder">只显示销售预下单，与正式销售订单分开。</small></label>
      <div class="md-fields"><label>类型<select v-model="form.material_type"><option value="fabric">面料</option><option value="accessory">辅料</option></select></label><label>物料名称<input v-model="form.material_name" required placeholder="客户指定或待寻找物料"/></label><label>规格要求<input v-model="form.requested_spec" placeholder="如成分、克重、尺寸"/></label><label>颜色 / 色号<input v-model="form.requested_color" placeholder="客户指定颜色"/></label></div>
      <label v-if="!editingId">关联款式<select v-model="form.pre_order_item_id"><option value="">请选择款式</option><option v-for="(item,index) in (preOrders.find(o=>o.id==form.pre_order_id)?.items || [])" :key="item.id" :value="item.id">{{item.product_name || '图片新款 '+(index+1)}} · {{item.style_no || '款号待版房填写'}}</option></select></label>
      <label>客户要求<textarea v-model="form.customer_requirements" rows="4" required placeholder="记录客户确认的材质、手感、颜色、质量标准、可接受范围等"></textarea></label>
      <div class="md-reference-upload"><div><b>客户参考图片</b><span>上传客户发来的面料 / 辅料效果图，业务确认时可与采购候选对照</span></div><ImageUpload v-model="form.reference_image_url" size="lg" title="客户参考图片"/></div>
      <div class="md-modal-foot"><span>{{ editingId ? '补充后将重新排入技术准入审核。' : '申请提交后，采购可开始第一轮市场寻样。' }}</span><button type="button" class="md-quiet" @click="showCreate=false">取消</button><button class="md-primary" :disabled="busy">{{ editingId ? '重新提交审核' : '提交寻样申请' }}</button></div>
    </form></div>
  </main>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { api } from '../api';
import { can } from '../store/permissions';
import ImageUpload from '../components/ImageUpload.vue';
import { openImage } from '../store/viewer';

const list = ref([]), preOrders = ref([]), loading = ref(false), busy = ref(false), q = ref(''), status = ref(''), showCreate = ref(false);
const expanded = ref(new Set()), searchNotes = reactive({}), candidates = reactive({}), editingId = ref(null);
const blankForm = () => ({ pre_order_id: '', pre_order_item_id:'', material_type: 'fabric', material_name: '', requested_spec: '', requested_color: '', customer_requirements: '', reference_image_url: '' });
const form = reactive(blankForm());
const canRequest = computed(() => can('development.write'));
const canSource = computed(() => can('purchase.write'));
const canReview = computed(() => can('development.write'));
const canPatternReview = computed(() => can('pattern.review'));
const filtered = computed(() => list.value.filter((r) => (!status.value || r.status === status.value) && (!q.value.trim() || [r.request_no,r.order_no,r.material_name,r.customer_name].some((x) => String(x || '').toLowerCase().includes(q.value.trim().toLowerCase())))));
const count = (s) => list.value.filter((r) => r.status === s).length;
const statusLabel = (s) => ({ search_required: '待重新寻样', searching: '采购寻样中', awaiting_business: '待业务确认', completed: '已完成' }[s] || s);
const patternReviewLabel = (s) => ({ blocked: '待业务确认面辅料', pending: '待技术审核准入打版', rejected: '打版准入已退回', approved: '已审核进入打版' }[s] || '待技术审核');
const fmt = (v) => v ? new Date(v).toLocaleString('zh-CN', { hour12: false }) : '—';
const eventLabel = (v) => ({ request_created: '提交申请', search_started: '采购开始寻样', candidate_returned: '候选回传', candidate_rejected: '业务拒绝候选', candidate_approved: '业务确认可用', pattern_entry_approved: '准入审核通过', pattern_entry_rejected: '准入审核退回', pattern_entry_resubmitted: '补充后重新提交准入审核' }[v] || v);
function toggle(id) { const n = new Set(expanded.value); n.has(id) ? n.delete(id) : n.add(id); expanded.value = n; }
function candidate(id) { if (!candidates[id]) candidates[id] = reactive({ candidate_name: '', candidate_spec: '', candidate_color: '', candidate_supplier: '', candidate_price: '', candidate_note: '', candidate_image_url: '' }); return candidates[id]; }
async function load() { loading.value = true; try { list.value = await api.materialDevRequests({}); expanded.value = new Set(list.value.filter((r) => ['searching', 'awaiting_business'].includes(r.status) || (r.status === 'completed' && ['pending','rejected'].includes(r.pattern_review_status))).map((r) => r.id)); } catch (e) { alert(e.message); } finally { loading.value = false; } }
async function openCreate() { try { preOrders.value = ((await api.preOrders({})) || []).filter(row => ['open','ready'].includes(row.status)); editingId.value = null; Object.assign(form, blankForm()); showCreate.value = true; } catch (e) { alert(e.message); } }
async function openResubmit(r) { try { preOrders.value = ((await api.preOrders({})) || []).filter(row => ['open','ready'].includes(row.status)); editingId.value = r.id; Object.assign(form, { pre_order_id: r.pre_order_id, material_type: r.material_type, material_name: r.material_name, requested_spec: r.requested_spec || '', requested_color: r.requested_color || '', customer_requirements: r.customer_requirements, reference_image_url: r.reference_image_url || '' }); showCreate.value = true; } catch (e) { alert(e.message); } }
async function create() { busy.value = true; try { if (editingId.value) await api.resubmitMaterialDevForPattern(editingId.value, form); else await api.createMaterialDevRequest(form); showCreate.value = false; editingId.value = null; await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
async function start(r) { busy.value = true; try { await api.startMaterialDevSearch(r.id, { search_note: searchNotes[r.id] || '' }); expanded.value = new Set([...expanded.value, r.id]); await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
async function returnCandidate(r, round) { const data = candidate(round.id); if (!data.candidate_name.trim()) return alert('请填写候选面辅料名称'); busy.value = true; try { await api.returnMaterialDevCandidate(round.id, data); expanded.value = new Set([...expanded.value, r.id]); await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
async function reject(r, round) { const reason = window.prompt('请写明不符合客户要求的原因，提交后采购可以重新寻找：'); if (!reason?.trim()) return; busy.value = true; try { await api.rejectMaterialDevCandidate(round.id, reason.trim()); expanded.value = new Set([...expanded.value, r.id]); await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
async function approve(r, round, archive) { if (!window.confirm(archive ? '确认候选可用，并同时加入面辅料档案？' : '确认候选符合要求并关闭本次新品开发？')) return; busy.value = true; try { await api.approveMaterialDevCandidate(round.id, { add_to_material_archive: archive }); expanded.value = new Set([...expanded.value, r.id]); await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
async function reviewForPattern(r, approve) { const note = approve ? (window.prompt('准入审核意见（可空）') || '') : String(window.prompt('请填写退回原因：') || '').trim(); if (!approve && !note) return; if (approve && !window.confirm('审核通过后将生成打版资料，并开放打版流程。继续？')) return; busy.value = true; try { await api.reviewMaterialDevForPattern(r.id, { approve, note }); await load(); } catch (e) { alert(e.message); } finally { busy.value = false; } }
onMounted(load);
</script>

<style scoped>
